import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { BrowserRouter as Router, useLocation } from 'react-router-dom';
import { useShellPathname } from './hooks/useShellPathname';
import { Provider, useDispatch } from 'react-redux';
import { navigateToUrl } from 'single-spa';
import {
  Sidebar,
  MobileNavRailTrigger,
  Topbar,
  useResponsive,
  BREAKPOINTS,
  type NavSection,
  hasValidAuthToken,
  AUTH_ACCESS_TOKEN_KEY,
  getAuthUser,
  AUTH_USER_STORAGE_KEY,
  GlobalToastHost,
  setUser,
  NAV_TOPBAR_AUTOHIDE,
  NAV_TOPBAR_LAYOUT_UNLOCK,
  isTopbarAutohideSuppressed,
  getLockedTopbarLayoutInset,
} from '@linm-soft-org/linm-web-common-components';
import {
  useUserPermissions,
  type AppPermissionDto,
} from './hooks/useUserPermissions';
import { isPathAllowedByPermissions } from './utils/pathPermission';
import { isPermissionsLocalModeActive } from './dev/isPermissionsLocalMode';
import { resolveNavTitle } from './utils/resolveNavTitle';
import { resolveLogoHomePath } from './utils/resolveLogoHomePath';
import { forceShellNavigate } from './utils/forceShellNavigate';
import { buildSectionsFromDB, type NavSectionExt } from './utils/buildSectionsFromDB';
import { NavTopbarNotificationSlot, NavTopbarRightActions } from './components/NavTopbarActions';
import { ShellWorkspaceTabProvider } from './workspace/ShellWorkspaceTabProvider';
import { resolveShellLogoLabel, resolveShellNavMain, resolveSidebarIconOnly } from './config/shellBranding';
import { useShellSidebarLogo } from './hooks/useShellSidebarLogo';
import { navStore } from './store/store';
import './styles/global.css';
import styles from './NavRoot.module.css';

const TOPBAR_HEIGHT = 72;
const AUTH_RETURN_URL_KEY = 'linm:auth:return-url';
const PUBLIC_PATHS = new Set([
  '/login',
  '/logout',
  '/session-expired',
  '/oidc-callback',
  '/oidc-silent-renew',
  '/forbidden',
  '/not-found',
]);

/** Guest SCYK report — no login (QR poster). Prefix match. */
const PUBLIC_PATH_PREFIXES = ['/scyk/bao-su-co', '/integration/users/register'];

/**
 * Phone web (`/m`, `/m/login`, `/m/web-rmms-*`).
 * Not a menu leaf. Exact prefix so `/mas` and `/messages` stay gated.
 */
function isMobilePhonePath(pathname: string): boolean {
  const n = normalizePath(pathname);
  return n === '/m' || n.startsWith('/m/');
}

/** Path prefixes where nav hides completely (ShellUrl iframe / FAB Home). */
const SHELL_EMBED_PATH_PREFIXES = ['/shell-url', '/shell'];

// ─── Types ────────────────────────────────────────────────────────────────────

interface StoredUser {
  fullName?: string;
  role?: string;
  package?: string;
  allowedCompanyCodes?: string[];
  canViewAllCompanies?: boolean;
}

const SIDEBAR_KEY = 'sidebar-collapsed-preference';
const ERR_SESSION_KEY = 'linm:error:original-path';

// ─── DB-driven nav builders ───────────────────────────────────────────────────

const ERP_FINANCE_PATH_PREFIXES = ['/kt', '/gt', '/tscd'];

function pathnameMatchesErpFinance(pathname: string): boolean {
  return ERP_FINANCE_PATH_PREFIXES.some(
    (p) => pathname === p || pathname.startsWith(`${p}/`),
  );
}

function normalizePath(path: string): string {
  if (!path) return '/';
  if (path === '/') return '/';
  return path.endsWith('/') ? path.slice(0, -1) : path;
}

const MOBILE_LOGIN_PATH = '/m/dang-nhap';

function isMobileLoginPath(pathname: string): boolean {
  const path = pathname.split('?')[0].split('#')[0];
  return normalizePath(path) === MOBILE_LOGIN_PATH;
}

function isRegisterCanvas(pathname: string): boolean {
  const n = normalizePath(pathname);
  return n === '/integration/users/register' || n.startsWith('/integration/users/register/');
}

function isPublicPath(pathname: string): boolean {
  const n = normalizePath(pathname);
  if (PUBLIC_PATHS.has(n) || isMobileLoginPath(n)) return true;
  return PUBLIC_PATH_PREFIXES.some((p) => n === p || n.startsWith(`${p}/`));
}

function isShellEmbedPath(pathname: string): boolean {
  const n = normalizePath(pathname);
  return SHELL_EMBED_PATH_PREFIXES.some((p) => n === p || n.startsWith(`${p}/`));
}

/** Empty while permissions load — do not fake accounts/permissions (causes Forbidden for limited packages). */
const ADMIN_NAV_FALLBACK: NavSection[] = [];

function getActiveLogoLabel(
  pathname: string,
  apps: AppPermissionDto[] | undefined,
): string {
  const shellLabel = resolveShellLogoLabel();
  if (shellLabel) return shellLabel;

  if (pathname.startsWith('/admin')) {
    return 'Quản trị hệ thống';
  }
  if (pathnameMatchesErpFinance(pathname)) {
    const fin = apps?.find((a) => a.appCode === 'erp-finance');
    if (fin) return fin.appName;
  }
  if (apps?.length) {
    const matched = [...apps]
      .filter((a) => a.uiBaseUrl)
      .sort((a, b) => (b.uiBaseUrl?.length ?? 0) - (a.uiBaseUrl?.length ?? 0))
      .find((a) => {
        const base = (a.uiBaseUrl ?? '').replace(/\/$/, '');
        return base && (pathname === base || pathname.startsWith(`${base}/`));
      });
    if (matched) return matched.appName;
  }
  return resolveShellNavMain();
}

const NavInner: React.FC = () => {
  const location = useLocation();
  /** Shell URL (single-spa) — used for menu shell + permissions API currentPath. */
  const shellPathname = useShellPathname();
  const pathname = shellPathname;
  const { isMobile, isSmallDesktop } = useResponsive();
  const {
    permissions,
    loading,
    pathRefreshing,
    sectionLoadingTitles,
    sectionHasMore,
    isSectionLazy,
    loadSectionNavItems,
    loadMoreSectionNavItems,
  } = useUserPermissions(shellPathname);

  const readStoredUser = (): StoredUser | null => {
    if (!hasValidAuthToken()) return null;
    const user = getAuthUser() as StoredUser | null;
    if (!user) return null;
    return {
      fullName: user.fullName,
      role: user.role,
      package: user.package,
      allowedCompanyCodes: user.allowedCompanyCodes,
      canViewAllCompanies: user.canViewAllCompanies,
    };
  };

  const [user, setUser] = useState<StoredUser | null>(() => readStoredUser());

  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(() => {
    if (typeof window === 'undefined') return false;
    const w = window.innerWidth;
    if (w < BREAKPOINTS.mobile) return false;
    if (w < BREAKPOINTS.tablet) return true;
    return localStorage.getItem(SIDEBAR_KEY) === 'collapsed';
  });

  const [isMobileSidebarOpen, setIsMobileSidebarOpen] = useState(false);
  const [pageTitle, setPageTitle] = useState('');
  const [topbarAutoHidden, setTopbarAutoHidden] = useState(false);
  const [topbarLayoutUnlockTick, setTopbarLayoutUnlockTick] = useState(0);
  const sidebarIconOnly = resolveSidebarIconOnly();
  const desktopIconRail = !isMobile && (sidebarIconOnly || isSidebarCollapsed);

  useShellSidebarLogo();

  useEffect(() => {
    if (isSmallDesktop && !isSidebarCollapsed) {
      setIsSidebarCollapsed(true);
    } else if (!isMobile && !isSmallDesktop) {
      setIsSidebarCollapsed(localStorage.getItem(SIDEBAR_KEY) === 'collapsed');
    } else if (isMobile) {
      setIsSidebarCollapsed(false);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isMobile, isSmallDesktop]);

  useEffect(() => {
    const handler = () => setIsMobileSidebarOpen((prev) => !prev);
    window.addEventListener('linm:nav:toggle-mobile', handler);
    return () => window.removeEventListener('linm:nav:toggle-mobile', handler);
  }, []);

  useEffect(() => {
    const syncUser = () => setUser(readStoredUser());
    syncUser();
    const onStorage = (e: StorageEvent) => {
      if (e.key === AUTH_USER_STORAGE_KEY || e.key === AUTH_ACCESS_TOKEN_KEY) syncUser();
    };
    window.addEventListener('storage', onStorage);
    window.addEventListener('linm:auth:changed', syncUser);
    window.addEventListener('linm:auth:token-changed', syncUser);
    return () => {
      window.removeEventListener('storage', onStorage);
      window.removeEventListener('linm:auth:changed', syncUser);
      window.removeEventListener('linm:auth:token-changed', syncUser);
    };
  }, [location.pathname]);

  useEffect(() => {
    setTopbarAutoHidden(false);
  }, [location.pathname]);

  useEffect(() => {
    const handler = (e: Event) => {
      if (isTopbarAutohideSuppressed() || getLockedTopbarLayoutInset()) return;
      const hidden = (e as CustomEvent<{ hidden?: boolean }>).detail?.hidden;
      if (typeof hidden === 'boolean') setTopbarAutoHidden(hidden);
    };
    window.addEventListener(NAV_TOPBAR_AUTOHIDE, handler);
    return () => window.removeEventListener(NAV_TOPBAR_AUTOHIDE, handler);
  }, []);

  useEffect(() => {
    const onUnlock = () => setTopbarLayoutUnlockTick((t) => t + 1);
    window.addEventListener(NAV_TOPBAR_LAYOUT_UNLOCK, onUnlock);
    return () => window.removeEventListener(NAV_TOPBAR_LAYOUT_UNLOCK, onUnlock);
  }, []);

  useEffect(() => {
    const isLogin = location.pathname === '/login';
    const guestCanvas = isLogin || isRegisterCanvas(location.pathname);
    const phone = isMobilePhonePath(pathname);
    const shellEmbed = isShellEmbedPath(pathname);
    const sidebarWidth = guestCanvas || phone || shellEmbed
      ? '0px'
      : isMobile
        ? isMobileSidebarOpen
          ? '280px'
          : '0px'
        : desktopIconRail
          ? '64px'
          : '280px';
    document.documentElement.style.setProperty('--sidebar-width', sidebarWidth);

    const topbarVisiblePx = isMobile ? 64 : TOPBAR_HEIGHT;
    document.documentElement.style.setProperty('--topbar-slide-height', `${topbarVisiblePx}px`);
    const locked = getLockedTopbarLayoutInset();
    const topbarLayoutInset =
      locked ?? (guestCanvas || phone || topbarAutoHidden || shellEmbed ? '0px' : `${topbarVisiblePx}px`);
    document.documentElement.style.setProperty('--topbar-height', topbarLayoutInset);
    document.documentElement.dataset.topbarAutohide = topbarAutoHidden ? 'true' : 'false';
  }, [
    desktopIconRail,
    isMobile,
    isMobileSidebarOpen,
    location.pathname,
    pathname,
    topbarAutoHidden,
    topbarLayoutUnlockTick,
  ]);

  useEffect(() => {
    const handler = (e: Event) => {
      const title = (e as CustomEvent<string>).detail;
      if (typeof title === 'string') setPageTitle(title);
    };
    window.addEventListener('linm:nav:set-title', handler);
    return () => window.removeEventListener('linm:nav:set-title', handler);
  }, []);

  useEffect(() => {
    setPageTitle(resolveNavTitle(pathname, permissions?.navItems ?? []));
  }, [pathname, permissions?.navItems]);

  useEffect(() => {
    const tokenExists = hasValidAuthToken();
    const currentPath = normalizePath(pathname);
    const fullCurrentUrl = `${window.location.pathname}${window.location.search}${window.location.hash}`;

    // Block all private URLs when unauthenticated and remember where to return after login.
    if (!tokenExists && isMobilePhonePath(currentPath) && !isMobileLoginPath(currentPath)) {
      sessionStorage.setItem(AUTH_RETURN_URL_KEY, fullCurrentUrl);
      navigateToUrl(MOBILE_LOGIN_PATH);
      return;
    }

    if (!tokenExists && !isPublicPath(currentPath)) {
      sessionStorage.setItem(AUTH_RETURN_URL_KEY, fullCurrentUrl);
      navigateToUrl('/login');
      return;
    }

    // Login success: desktop stays on `/login` return; phone stays under `/m`.
    if (tokenExists && (currentPath === '/login' || isMobileLoginPath(currentPath))) {
      const returnUrl = sessionStorage.getItem(AUTH_RETURN_URL_KEY);
      const phoneLogin = isMobileLoginPath(currentPath);
      const returnOk =
        !!returnUrl &&
        returnUrl !== '/login' &&
        !isMobileLoginPath(returnUrl) &&
        (!phoneLogin || returnUrl === '/m' || returnUrl.startsWith('/m/'));
      sessionStorage.removeItem(AUTH_RETURN_URL_KEY);
      if (returnOk && returnUrl) {
        navigateToUrl(returnUrl);
      } else if (phoneLogin) {
        navigateToUrl('/m/trang-chu');
      }
    }
  }, [pathname, location.search, location.hash]);

  useEffect(() => {
    if (!hasValidAuthToken()) return;
    if (isPublicPath(pathname)) return;
    if (isMobilePhonePath(pathname)) return;
    if (isShellEmbedPath(pathname)) return;
    if (pathname === '/') return;
    if (loading || pathRefreshing) return;
    if (isPermissionsLocalModeActive()) return;

    const navItems = permissions?.navItems ?? [];
    const allowedPaths = permissions?.allowedPaths;
    if (!navItems.length && !allowedPaths?.length) return;

    if (
      !isPathAllowedByPermissions(pathname, navItems, allowedPaths, {
        isAdminUser: user?.role === 'admin',
      })
    ) {
      try { sessionStorage.setItem(ERR_SESSION_KEY, pathname); } catch { /* noop */ }
      navigateToUrl('/forbidden');
    }
  }, [pathname, loading, pathRefreshing, permissions?.navItems, permissions?.allowedPaths, user?.role]);

  const handleToggleSidebar = useCallback(() => {
    setIsSidebarCollapsed((prev) => {
      const next = !prev;
      if (!isMobile) localStorage.setItem(SIDEBAR_KEY, next ? 'collapsed' : 'expanded');
      return next;
    });
  }, [isMobile]);

  const handleNavigate = useCallback((path: string) => {
    forceShellNavigate(path, pathname);
    if (isMobile) setIsMobileSidebarOpen(false);
  }, [isMobile, pathname]);

  const handleLogout = useCallback(() => {
    sessionStorage.removeItem(AUTH_RETURN_URL_KEY);
    navigateToUrl('/logout');
  }, []);

  const isAdmin = user?.role === 'admin';

  const sections: NavSectionExt[] = useMemo(() => {
    const navItems = permissions?.navItems;

    if (pathname.startsWith('/admin')) {
      if (navItems?.length) {
        const built = buildSectionsFromDB(
          navItems.filter(
            (i) => i.isGroup || (i.path != null && i.path.startsWith('/admin')),
          ),
        );
        if (built.length) return built;
      }
      return ADMIN_NAV_FALLBACK;
    }

    if (navItems?.length) {
      return buildSectionsFromDB(navItems.filter((i) => !i.path?.startsWith('/admin')));
    }

    return [];
  }, [pathname, permissions?.navItems]);

  const logoLabel = useMemo(
    () => getActiveLogoLabel(pathname, permissions?.apps),
    [pathname, permissions?.apps],
  );

  const logoHomePath = useMemo(
    () => resolveLogoHomePath(pathname, permissions?.navItems, permissions?.packageDefaultUrl),
    [pathname, permissions?.navItems, permissions?.packageDefaultUrl],
  );

  const fullName = user?.fullName || 'Người dùng';
  const parts = fullName.trim().split(' ');
  const userInitials =
    parts.length >= 2
      ? (parts[parts.length - 2].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase()
      : fullName.charAt(0).toUpperCase();

  const roleLabel =
    user?.role === 'admin'   ? 'Quản trị viên'
    : user?.role === 'manager' ? 'Quản lý'
    : user?.role === 'staff'   ? 'Nhân viên'
    : 'Người dùng';

  if (pathname === '/login' || pathname === '/logout' || isRegisterCanvas(pathname)) return null;
  if (isMobilePhonePath(pathname)) return null;
  if (isShellEmbedPath(pathname)) return null;

  const menuReady = (permissions?.navItems?.length ?? 0) > 0;
  const showMainContentSkeleton = pathRefreshing && menuReady;
  const sidebarOffsetPx = isMobile
    ? isMobileSidebarOpen
      ? 280
      : 0
    : desktopIconRail
      ? 64
      : 280;

  return (
    <ShellWorkspaceTabProvider sidebarOffsetPx={sidebarOffsetPx}>
    <>
      {showMainContentSkeleton ? (
        <div
          className={styles.mainContentSkeleton}
          role="status"
          aria-live="polite"
          aria-busy="true"
          aria-label="Đang tải trang"
          style={{
            top: topbarAutoHidden ? 0 : undefined,
            left: isMobile ? 0 : desktopIconRail ? 64 : 280,
          }}
        >
          <div className={`${styles.mainContentSkeletonBar} ${styles.mainContentSkeletonBarWide}`} />
          <div className={`${styles.mainContentSkeletonBar} ${styles.mainContentSkeletonBarMid}`} />
          <div className={styles.mainContentSkeletonGrid}>
            <div className={styles.mainContentSkeletonCard} />
            <div className={styles.mainContentSkeletonCard} />
            <div className={styles.mainContentSkeletonCard} />
          </div>
          <div className={`${styles.mainContentSkeletonBar} ${styles.mainContentSkeletonBarFull}`} />
          <div className={`${styles.mainContentSkeletonBar} ${styles.mainContentSkeletonBarFull}`} />
        </div>
      ) : null}
      <div className={styles.sidebarHost}>
        <Sidebar
          sections={sections as NavSection[]}
          activePath={pathname}
          userName={fullName}
          userRole={roleLabel}
          userInitials={userInitials}
          onNavigate={handleNavigate}
          onLogout={handleLogout}
          isCollapsed={isMobile ? false : desktopIconRail}
          onToggleCollapse={isMobile || sidebarIconOnly ? undefined : handleToggleSidebar}
          isMobile={isMobile}
          isSmallDesktop={isSmallDesktop}
          isOpen={isMobileSidebarOpen}
          onRequestOpen={() => setIsMobileSidebarOpen(true)}
          onRequestClose={() => setIsMobileSidebarOpen(false)}
          logoLabel={logoLabel}
          logoHomePath={logoHomePath}
          menuSkeleton={loading && !permissions?.navItems?.length}
          sectionLoadingTitles={sectionLoadingTitles}
          sectionHasMore={sectionHasMore}
          isSectionLazy={isSectionLazy}
          onSectionExpand={loadSectionNavItems}
          onSectionLoadMore={loadMoreSectionNavItems}
        />
      </div>
      <div
        className={[styles.topbarHost, topbarAutoHidden ? styles.topbarHostHidden : ''].filter(Boolean).join(' ')}
        style={{
          left: isMobile ? 0 : desktopIconRail ? 64 : 280,
        }}
      >
        <Topbar
          title={pageTitle}
          showMenuButton={false}
          leftSlot={
            isMobile && !isMobileSidebarOpen ? (
              <MobileNavRailTrigger onOpen={() => setIsMobileSidebarOpen(true)} />
            ) : undefined
          }
          notificationSlot={
            <NavTopbarNotificationSlot onNavigate={handleNavigate} />
          }
          rightSlot={
            <NavTopbarRightActions
              onNavigate={handleNavigate}
              isAdmin={isAdmin}
              isMobile={isMobile}
              allowedCompanyCodes={user?.allowedCompanyCodes}
              canViewAllCompanies={user?.canViewAllCompanies}
            />
          }
        />
      </div>
    </>
    </ShellWorkspaceTabProvider>
  );
};

/** Sync Redux auth slice from secure storage (Home login writes tokens; Nav mounts later). */
const NavAuthHydrate: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const dispatch = useDispatch();

  useEffect(() => {
    const sync = () => {
      if (!hasValidAuthToken()) return;
      const stored = getAuthUser();
      if (stored) dispatch(setUser(stored));
    };
    sync();
    window.addEventListener('linm:auth:changed', sync);
    window.addEventListener('linm:auth:token-changed', sync);
    return () => {
      window.removeEventListener('linm:auth:changed', sync);
      window.removeEventListener('linm:auth:token-changed', sync);
    };
  }, [dispatch]);

  return <>{children}</>;
};

const NavRoot: React.FC = () => (
  <Provider store={navStore}>
    <GlobalToastHost />
    <Router>
      <NavAuthHydrate>
        <NavInner />
      </NavAuthHydrate>
    </Router>
  </Provider>
);

export default NavRoot;
