import type { NavMenuItemDto } from '../hooks/useUserPermissions';

/** Dashboard slot — not a sidebar leaf. Parcel names (`@linm/…`) are not routes. */
export function isDashboardWidgetNavItem(
  item: Pick<NavMenuItemDto, 'code' | 'menuType' | 'redirectTo' | 'isGroup'> | null | undefined,
): boolean {
  if (!item || item.isGroup) return false;
  if (item.menuType === 'widget') return true;
  if (typeof item.code === 'string' && item.code.startsWith('dashboard-widget-')) return true;
  const target = (item.redirectTo ?? '').trim();
  return target.startsWith('@');
}

export function isParcelName(value: string | null | undefined): boolean {
  return (value ?? '').trim().startsWith('@');
}

/** Real sidebar / shell route — not `#`, parcel `@linm/…`, or empty. */
export function isNavigableNavPath(path: string | null | undefined): boolean {
  const t = (path ?? '').trim();
  if (!t || t === '#') return false;
  if (t.startsWith('@')) return false;
  return t.startsWith('/');
}
