import type { NavSectionMetaDto } from '../hooks/useUserPermissions';

/**
 * Lazy only when Auth explicitly says so.
 * Missing meta → treat as eager so a partial/old payload cannot hide L1 groups
 * or 403 routes that were already granted.
 */
export function sectionRequiresLazyLoad(
  sectionTitle: string,
  meta: NavSectionMetaDto[] | undefined,
): boolean {
  if (!meta?.length) return false;
  const row = meta.find((s) => s.sectionTitle === sectionTitle);
  return row?.requiresLazyLoad === true;
}
