import type { NavMenuItemDto } from '../hooks/useUserPermissions';
import { isDashboardWidgetNavItem, isNavigableNavPath, isParcelName } from './isDashboardWidgetNavItem';

export type NavItemExt = {
  id: string;
  label: string;
  icon: string;
  path: string;
  children?: NavItemExt[];
};

export type NavSectionExt = { title: string; items: NavItemExt[] };

export function toNavItem(dto: NavMenuItemDto): NavItemExt {
  const redirectIsRoute =
    !!dto.redirectTo && !isParcelName(dto.redirectTo) && !isDashboardWidgetNavItem(dto);
  const raw =
    redirectIsRoute &&
    (dto.mountType === 'redirect' || dto.mountType === 'shell' || dto.mountType === 'parcel')
      ? (dto.redirectTo ?? dto.path)
      : dto.path;
  const navPath = isNavigableNavPath(raw) ? (raw ?? '').trim() : '';
  return { id: dto.code, label: dto.label, icon: dto.icon ?? 'fas fa-circle', path: navPath };
}

function firstNavigablePath(items: NavItemExt[]): string {
  return items.find((i) => isNavigableNavPath(i.path))?.path ?? '';
}

/**
 * Authen groups use path `#`. Sidebar treats a 1-item section with no children as a
 * shortcut — `#` becomes `/` then RMMS packageDefaultUrl (`/so-ts`). Flatten one-child
 * groups so L0 "Bảng điều khiển" navigates to `/dashboard`.
 */
export function buildSectionsFromDB(navItems: NavMenuItemDto[]): NavSectionExt[] {
  const sorted = [...navItems].sort((a, b) =>
    a.sectionOrderIndex !== b.sectionOrderIndex
      ? a.sectionOrderIndex - b.sectionOrderIndex
      : a.orderIndex - b.orderIndex,
  );

  const groupMap = new Map<string, NavMenuItemDto>(
    sorted.filter((i) => i.isGroup).map((i) => [i.code, i]),
  );
  const childrenByGroup = new Map<string, NavMenuItemDto[]>();
  const orphanLeaves: NavMenuItemDto[] = [];

  for (const item of sorted.filter((i) => !i.isGroup && i.path && !isDashboardWidgetNavItem(i))) {
    if (item.parentCode && groupMap.has(item.parentCode)) {
      const arr = childrenByGroup.get(item.parentCode) ?? [];
      arr.push(item);
      childrenByGroup.set(item.parentCode, arr);
    } else {
      orphanLeaves.push(item);
    }
  }

  type SectionAcc = { title: string; items: NavItemExt[]; order: number };
  const sectionAcc = new Map<string, SectionAcc>();

  const ensureSection = (title: string, order: number): NavItemExt[] => {
    const existing = sectionAcc.get(title);
    if (!existing) {
      sectionAcc.set(title, { title, items: [], order });
      return sectionAcc.get(title)!.items;
    }
    existing.order = Math.min(existing.order, order);
    return existing.items;
  };

  for (const group of [...groupMap.values()].sort((a, b) => a.orderIndex - b.orderIndex)) {
    const title = group.sectionTitle ?? 'Menu';
    const order = group.sectionOrderIndex ?? group.orderIndex;
    const children = (childrenByGroup.get(group.code) ?? [])
      .sort((a, b) => a.orderIndex - b.orderIndex)
      .map((c) => toNavItem(c));

    if (children.length === 0) {
      const widgetSiblings = sorted.filter(
        (i) => !i.isGroup && i.parentCode === group.code && isDashboardWidgetNavItem(i),
      );
      const fallback = widgetSiblings.find((w) => isNavigableNavPath(w.path))?.path ?? '';
      if (fallback) {
        ensureSection(title, order).push({
          id: group.code,
          label: group.label,
          icon: group.icon ?? 'fas fa-th-large',
          path: fallback,
        });
        continue;
      }
      // Keep empty L1 groups visible while sibling leaves are still lazy-loading.
      ensureSection(title, order).push({
        ...toNavItem(group),
        path: '',
        children: [],
      });
      continue;
    }

    if (children.length === 1) {
      // Keep L1 group label (e.g. "03. AI kiểm định…") — leaf name has no PL01 number.
      const child = children[0];
      ensureSection(title, order).push({
        ...child,
        label: group.label || child.label,
        icon: group.icon ?? child.icon,
      });
      continue;
    }

    const groupItem = toNavItem(group);
    ensureSection(title, order).push({
      ...groupItem,
      path: firstNavigablePath(children) || groupItem.path,
      children,
    });
  }

  for (const leaf of orphanLeaves) {
    const title = leaf.sectionTitle ?? 'Menu';
    const order = leaf.sectionOrderIndex ?? leaf.orderIndex;
    ensureSection(title, order).push(toNavItem(leaf));
  }

  return [...sectionAcc.values()]
    .sort((a, b) => a.order - b.order || a.title.localeCompare(b.title, 'vi'))
    .map(({ title, items }) => ({ title, items }));
}
